/* ========================================
   加载动画 - 花瓣旋转
   ======================================== */
.style_dot-flashing__8L91Q.style_text__zGhNq {
  display: none !important;
}

.flex.items-center.justify-center.w-6.h-5 {
  position: relative !important;
  overflow: visible !important;
  width: 50px !important;
  height: 40px !important;
}

.flex.items-center.justify-center.w-6.h-5::before {
  content: '✿' !important;
  position: absolute !important;
  color: #F8A5B4 !important;
  font-size: 26px !important;
  animation: flower-spin 2s linear infinite !important;
  filter: drop-shadow(0 0 12px rgba(248, 165, 180, 0.8)) !important;
}

.flex.items-center.justify-center.w-6.h-5::after {
  content: '❀' !important;
  position: absolute !important;
  color: #FFD1DC !important;
  font-size: 16px !important;
  animation: flower-spin-reverse 2.8s linear infinite !important;
  filter: drop-shadow(0 0 8px rgba(255, 209, 220, 0.8)) !important;
}

@keyframes flower-spin {
  0%   { transform: rotate(0deg) scale(1); opacity: 0.8; }
  50%  { transform: rotate(180deg) scale(1.2); opacity: 1; }
  100% { transform: rotate(360deg) scale(1); opacity: 0.8; }
}

@keyframes flower-spin-reverse {
  0%   { transform: rotate(360deg) scale(1); opacity: 0.7; }
  50%  { transform: rotate(180deg) scale(1.15); opacity: 1; }
  100% { transform: rotate(0deg) scale(1); opacity: 0.7; }
}


/* ========================================
   全局样式
   ======================================== */
details {
  margin: 12px 0;
}

details > summary {
  cursor: pointer;
  user-select: none;
  padding: 12px 16px;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(255, 158, 205, 0.1) 0%, rgba(168, 230, 207, 0.1) 100%);
  border: 2px solid rgba(255, 158, 205, 0.2);
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  font-weight: 600;
  color: #333;
  margin-bottom: 10px;
}

details > summary:hover {
  background: linear-gradient(135deg, rgba(255, 158, 205, 0.15) 0%, rgba(168, 230, 207, 0.15) 100%);
  border-color: rgba(255, 158, 205, 0.4);
  transform: translateX(4px);
}

details[open] > summary {
  background: linear-gradient(135deg, rgba(255, 158, 205, 0.2) 0%, rgba(168, 230, 207, 0.2) 100%);
  border-color: rgba(255, 158, 205, 0.5);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

details > summary::marker,
details > summary::-webkit-details-marker {
  display: none;
}

details > summary::before {
  content: '▶ ';
  display: inline-block;
  margin-right: 8px;
  transition: transform 0.3s ease;
  color: #ff9ecd;
}

details[open] > summary::before {
  transform: rotate(90deg);
}

/* ========================================
   思维链容器
   ======================================== */
.thinking-box {
  background: linear-gradient(135deg, rgba(255, 245, 250, 0.95) 0%, rgba(240, 248, 255, 0.95) 100%);
  border: 2px solid rgba(122, 162, 247, 0.2);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  animation: cardSlideIn 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.thinking-header {
  font-weight: 700;
  color: #7aa2f7;
  font-size: 0.95em;
  padding: 8px 12px;
  background: rgba(122, 162, 247, 0.08);
  border-left: 3px solid #7aa2f7;
  border-radius: 4px;
  animation: slideIn 0.5s ease-out forwards;
}

.thinking-content {
  color: #666;
  font-family: 'Courier New', monospace;
  font-size: 0.9em;
  line-height: 1.6;
  padding: 8px 12px;
  background: rgba(255, 255, 255, 0.6);
  border-radius: 6px;
  white-space: pre-wrap;
  word-break: break-word;
  animation: slideIn 0.5s ease-out forwards;
}

/* ========================================
   场景卡片
   ======================================== */
.scene-card {
  background: linear-gradient(135deg, rgba(255, 240, 245, 0.95) 0%, rgba(255, 248, 250, 0.95) 100%);
  border: 2px solid rgba(255, 158, 205, 0.2);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  animation: cardSlideIn 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.scene-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.6);
  border-left: 4px solid transparent;
  border-radius: 6px;
  transition: all 0.3s ease;
  animation: rowSlideIn 0.5s ease-out forwards;
  opacity: 0;
}

.scene-row:nth-child(1) { animation-delay: 0.05s; }
.scene-row:nth-child(2) { animation-delay: 0.1s; }
.scene-row:nth-child(3) { animation-delay: 0.15s; }
.scene-row:nth-child(4) { animation-delay: 0.2s; }
.scene-row:nth-child(5) { animation-delay: 0.25s; }

.scene-row:hover {
  background: rgba(255, 158, 205, 0.08);
  border-left-color: #ff9ecd;
  transform: translateX(4px);
}

.scene-label {
  font-weight: 600;
  color: #ff9ecd;
  min-width: 80px;
  font-size: 0.95em;
}

.scene-value {
  color: #555;
  text-align: right;
  flex: 1;
  margin-left: 12px;
}

/* ========================================
   玩家卡片
   ======================================== */
