  font-weight: bold;
  background: linear-gradient(135deg, #a8e6cf, #7ee8c1);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.player-title {
  font-size: 0.9em;
  color: #999;
}

.player-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.player-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.6);
  border-left: 4px solid rgba(168, 230, 207, 0.3);
  border-radius: 6px;
  transition: all 0.3s ease;
  animation: rowSlideIn 0.5s ease-out forwards;
  opacity: 0;
}

.player-row:nth-child(1) { animation-delay: 0.1s; }
.player-row:nth-child(2) { animation-delay: 0.15s; }
.player-row:nth-child(3) { animation-delay: 0.2s; }
.player-row:nth-child(4) { animation-delay: 0.25s; }

.player-row:hover {
  background: rgba(168, 230, 207, 0.08);
  border-left-color: #a8e6cf;
  transform: translateX(4px);
}

.player-label {
  font-weight: 600;
  color: #a8e6cf;
  min-width: 80px;
  font-size: 0.95em;
}

.player-value {
  color: #555;
  text-align: right;
  flex: 1;
  margin-left: 12px;
}

.player-footer {
  padding: 12px 16px;
  text-align: center;
  background: rgba(168, 230, 207, 0.08);
  border-top: 2px dashed rgba(168, 230, 207, 0.2);
  color: #999;
  font-size: 0.9em;
}

/* ========================================
   NPC卡片（小雨）
   ======================================== */
.npc-detail-card {
  background: linear-gradient(135deg, rgba(255, 240, 245, 0.95) 0%, rgba(255, 248, 250, 0.95) 100%);
  border: 2px solid rgba(255, 158, 205, 0.3);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 8px 32px rgba(255, 158, 205, 0.15), inset 0 0 20px rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(10px);
  animation: cardSlideIn 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.npc-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px;
  background: linear-gradient(135deg, rgba(255, 158, 205, 0.1) 0%, rgba(168, 230, 207, 0.1) 100%);
  border-bottom: 2px solid rgba(255, 158, 205, 0.15);
  position: relative;
  overflow: hidden;
}

.npc-header::before {
  content: '';
  position: absolute;
  top: 0;
  right: -100px;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, rgba(255, 158, 205, 0.2) 0%, transparent 70%);
  animation: floatLight 6s ease-in-out infinite;
}

@keyframes floatLight {
  0%, 100% { transform: translate(0, 0); }
  50% { transform: translate(50px, 30px); }
}

.npc-avatar {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  border: 3px solid rgba(255, 158, 205, 0.5);
  box-shadow: 0 4px 15px rgba(255, 158, 205, 0.3), inset 0 0 10px rgba(255, 255, 255, 0.5);
  position: relative;
  animation: avatarGlowPink 3s ease-in-out infinite;
}

.npc-avatar::after {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: conic-gradient(from 0deg, #ff9ecd, #a8e6cf, #ff9ecd);
  z-index: -1;
  animation: avatarSpin 3s linear infinite;
}

@keyframes avatarSpin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes avatarGlowPink {
  0%, 100% {
    box-shadow: 0 4px 15px rgba(255, 158, 205, 0.3), inset 0 0 10px rgba(255, 255, 255, 0.5);
  }
  50% {
    box-shadow: 0 8px 25px rgba(255, 158, 205, 0.5), inset 0 0 15px rgba(255, 255, 255, 0.8);
  }
}

.npc-av-3 {
  background-image: url('https://img.cdn1.vip/i/69db724276397_1775989314.jpg');
}

.npc-info {
  flex: 1;
  position: relative;
  z-index: 1;
}

.npc-title {
  font-size: 1.3em;
  font-weight: bold;
  background: linear-gradient(135deg, #ff9ecd 0%, #f7768e 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: titleGlow 2s ease-in-out infinite;
}

@keyframes titleGlow {
  0%, 100% {
    filter: drop-shadow(0 0 3px rgba(255, 158, 205, 0.3));
  }
  50% {
    filter: drop-shadow(0 0 8px rgba(255, 158, 205, 0.6));
  }
}

.npc-sub {
  font-size: 0.85em;
  color: #999;
  font-weight: 500;
}

.npc-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.npc-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 12px 14px;
  background: rgba(255, 255, 255, 0.6);
  border-left: 4px solid transparent;
  border-radius: 8px;
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  animation: rowSlideIn 0.5s ease-out forwards;
  opacity: 0;
}

.npc-row:nth-child(1) { animation-delay: 0.1s; }
.npc-row:nth-child(2) { animation-delay: 0.15s; }
.npc-row:nth-child(3) { animation-delay: 0.2s; }
.npc-row:nth-child(4) { animation-delay: 0.25s; }
.npc-row:nth-child(5) { animation-delay: 0.3s; }
.npc-row:nth-child(6) { animation-delay: 0.35s; }
.npc-row:nth-child(7) { animation-delay: 0.4s; }

.npc-row:hover {
  background: rgba(255, 158, 205, 0.08);
  border-left-color: #ff9ecd;
  transform: translateX(4px);
  box-shadow: 0 4px 12px rgba(255, 158, 205, 0.15);
}

.npc-label {
  font-weight: 600;
  color: #ff9ecd;
  min-width: 75px;
  font-size: 0.9em;
}

.npc-value {
  color: #555;
  text-align: right;
  flex: 1;
  margin-left: 15px;
  word-break: break-word;
  line-height: 1.5;
}

.highlight {
  color: #ff9ecd;
  font-weight: bold;
  background: rgba(255, 158, 205, 0.1);
  padding: 2px 6px;
  border-radius: 4px;
}

.npc-divider {
  height: 2px;
  margin: 15px 0;
  background: linear-gradient(90deg, transparent 0%, rgba(255, 158, 205, 0.3) 25%, rgba(255, 158, 205, 0.6) 50%, rgba(255, 158, 205, 0.3) 75%, transparent 100%);
  position: relative;
  overflow: hidden;
}

.npc-divider::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent 0%, #ff9ecd 25%, #ff9ecd 75%, transparent 100%);
  animation: dividerFlow 2s infinite;
}

@keyframes dividerFlow {
  0% { left: -100%; }
  100% { left: 100%; }
}

.npc-footer {
  padding: 14px 20px;
  background: linear-gradient(135deg, rgba(255, 158, 205, 0.08) 0%, rgba(168, 230, 207, 0.08) 100%);
  border-top: 2px dashed rgba(255, 158, 205, 0.2);
  border-bottom-left-radius: 10px;
  border-bottom-right-radius: 10px;
  position: relative;
  overflow: hidden;
}

.npc-footer::before {
  content: '';
  position: absolute;
  bottom: -50px;
  left: -50px;
  width: 150px;
  height: 150px;
  background: radial-gradient(circle, rgba(255, 158, 205, 0.15) 0%, transparent 70%);
  animation: floatLight2 8s ease-in-out infinite;
}

@keyframes floatLight2 {
  0%, 100% { transform: translate(0, 0); }
  50% { transform: translate(30px, -30px); }
}

.npc-footer small {
  color: #666;
  font-style: italic;
  font-size: 0.95em;
  line-height: 1.6;
  display: block;
  position: relative;
  z-index: 1;
}

.npc-footer small::before {
  content: '「';
  color: #ff9ecd;
  margin-right: 4px;
}

.npc-footer small::after {
  content: '」';
  color: #ff9ecd;
  margin-left: 4px;
}

/* ========================================
