.stream-row:nth-child(1) { animation-delay: 0.1s; }
.stream-row:nth-child(2) { animation-delay: 0.15s; }
.stream-row:nth-child(3) { animation-delay: 0.2s; }
.stream-row:nth-child(4) { animation-delay: 0.25s; }
.stream-row:nth-child(5) { animation-delay: 0.3s; }

.stream-row:hover {
