/* ========================================
   行动卡片
   ======================================== */
.action-card {
  background: linear-gradient(135deg, rgba(255, 240, 245, 0.95) 0%, rgba(255, 248, 250, 0.95) 100%);
  border: 2px solid rgba(255, 158, 205, 0.2);
  border-radius: 12px;
  padding: 20px;
  animation: cardSlideIn 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.action-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 12px;
}

.action-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.7);
  border: 2px solid;
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  cursor: pointer;
  animation: slideUp 0.5s ease-out forwards;
  opacity: 0;
}

.action-item:nth-child(1) { animation-delay: 0.1s; }
.action-item:nth-child(2) { animation-delay: 0.2s; }
.action-item:nth-child(3) { animation-delay: 0.3s; }
.action-item:nth-child(4) { animation-delay: 0.4s; }
.action-item:nth-child(5) { animation-delay: 0.5s; }

.action-item:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.1);
}

.action-a { border-color: rgba(255, 158, 205, 0.5); }
.action-a:hover { background: rgba(255, 158, 205, 0.1); }

.action-b { border-color: rgba(122, 162, 247, 0.5); }
.action-b:hover { background: rgba(122, 162, 247, 0.1); }

.action-c { border-color: rgba(187, 134, 252, 0.5); }
.action-c:hover { background: rgba(187, 134, 252, 0.1); }

.action-d { border-color: rgba(168, 230, 207, 0.5); }
.action-d:hover { background: rgba(168, 230, 207, 0.1); }

.action-free { border-color: rgba(255, 182, 193, 0.5); }
.action-free:hover { background: rgba(255, 182, 193, 0.1); }

.action-label {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  font-weight: bold;
  color: white;
  font-size: 1.1em;
  flex-shrink: 0;
}

.action-a .action-label { background: linear-gradient(135deg, #ff9ecd, #f7768e); }
.action-b .action-label { background: linear-gradient(135deg, #7aa2f7, #89ddff); }
.action-c .action-label { background: linear-gradient(135deg, #bb9af7, #c0caf5); }
.action-d .action-label { background: linear-gradient(135deg, #a8e6cf, #7ee8c1); }
.action-free .action-label { background: linear-gradient(135deg, #ffb6c1, #ffc0cb); }

.action-content {
  flex: 1;
}

.action-title {
  font-weight: 600;
  color: #333;
  font-size: 0.9em;
  margin-bottom: 4px;
  line-height: 1.3;
}

.action-effect {
  color: #999;
  font-size: 0.8em;
  font-style: italic;
}

/* ========================================
   动画库
   ======================================== */
@keyframes cardSlideIn {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes rowSlideIn {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(-15px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(15px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ========================================
   响应式
   ======================================== */
@media (max-width: 768px) {
  .npc-header,
  .player-header,
  .stream-header {
    flex-wrap: wrap;
  }

  .npc-row,
  .player-row,
  .scene-row,
  .stream-row {
    flex-direction: column;
    gap: 6px;
  }

  .npc-value,
  .player-value,
  .scene-value,
  .stream-value {
    text-align: left;
    margin-left: 0;
  }

  .action-grid {
    grid-template-columns: 1fr;
  }
}
